class ADS1115_Simulator(BaseVirtualSensor):
    REG_WIDTH = 16  # 16-bit registers

    def __init__(self):
        # Initialize all registers with their reset values
        self.regs = {
            0x00: 0x0000,  # CONVERSION
            0x01: 0x8583,  # CONFIG
            0x02: 0x8000,  # LO_THRESH
            0x03: 0x7FFF   # HI_THRESH
        }

    def read_register(self, addr: int, nbytes: int = 2) -> int:
        # Return the reset value of the register
        return self.regs[addr]

    def write_register(self, addr: int, data: int, nbytes: int = 2) -> None:
        # If the register is read-only, return immediately
        if addr in [0x00, 0x02, 0x03]:
            return
        # If nbytes is 1, update only the relevant bits
        if nbytes == 1:
            if addr == 0x01:
                # Update only OS, MUX, PGA, MODE, DR fields
                self.regs[addr] = (data & 0xF800) | (self.regs[addr] & 0x07FF)
            elif addr == 0x02:
                # Update only THRESH field
                self.regs[addr] = (data & 0x00FF) | (self.regs[addr] & 0xFF00)
            elif addr == 0x03:
                # Update only THRESH field
                self.regs[addr] = (data & 0x00FF) | (self.regs[addr] & 0xFF00)
        else:
            # For other registers, update the entire register
            self.regs[addr] = data
